parameters.inputSchema:
{
  "type": "object",
  "required": [
    "reply",
    "escalate"
  ],
  "properties": {
    "reply": {
      "type": "string",
      "description": "What to say to the customer in this turn."
    },
    "escalate": {
      "type": "boolean",
      "description": "True only in the 3 specified escalation situations."
    },
    "escalation": {
      "type": [
        "object",
        "null"
      ],
      "properties": {
        "reason_code": {
          "type": "string",
          "enum": [
            "kb_gap",
            "not_in_catalog",
            "ready_to_book"
          ]
        },
        "customer_name": {
          "type": "string"
        },
        "customer_email": {
          "type": "string"
        },
        "customer_whatsapp": {
          "type": "string"
        },
        "conversation_summary": {
          "type": "string"
        },
        "package_or_destination": {
          "type": "string"
        },
        "proposed_itinerary": {
          "type": "string"
        }
      }
    }
  }
}

assignments.value:
={{ (() => {
  const esc = $('Musafir Agent').item.json.output.escalation || {};
  const reasonLabels = { kb_gap: "Question outside current knowledge base", not_in_catalog: "Interested in a destination/package not yet in catalogue", ready_to_book: "Ready to finalize — wants firm price / booking" };
  const reasonLabel = reasonLabels[esc.reason_code] || esc.reason_code || "General enquiry";
  const name = esc.customer_name;
  return `New Musafir Enquiry — ${reasonLabel}` + (name ? ` — ${name}` : "");
})() }}

={{ (() => {
  const esc = $('Musafir Agent').item.json.output.escalation || {};
  const reasonLabels = { kb_gap: "Question outside current knowledge base", not_in_catalog: "Interested in a destination/package not yet in catalogue", ready_to_book: "Ready to finalize — wants firm price / booking" };
  const reasonLabel = reasonLabels[esc.reason_code] || esc.reason_code || "General enquiry";
  const timestamp = $now.setZone("Asia/Kolkata").toFormat("dd LLLL yyyy, HH:mm 'IST'");
  const name = esc.customer_name || "Not provided";
  const email = esc.customer_email || "";
  const whatsapp = esc.customer_whatsapp || "";
  const summary = esc.conversation_summary || "Not provided";
  const packageOrDestination = esc.package_or_destination || "Not specified";
  const itinerary = esc.proposed_itinerary || "";
  const itineraryRow = itinerary
    ? `<h3 style="margin:20px 0 6px;font-size:14px;color:#334155;">Proposed Itinerary</h3><p style="margin:0 0 16px;font-size:14px;line-height:1.5;white-space:pre-line;">${itinerary}</p>`
    : "";
  return `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#1e293b;">
  <h2 style="color:#0f766e;margin:0 0 4px;">Meridian &amp; Co. — New Musafir Enquiry</h2>
  <p style="margin:0 0 16px;color:#64748b;font-size:13px;">${reasonLabel} &middot; ${timestamp}</p>
  <table style="width:100%;border-collapse:collapse;background:#f0fdfa;border:1px solid #99f6e4;border-radius:8px;">
    <tr><td style="padding:8px 12px;font-weight:600;width:140px;">Name</td><td style="padding:8px 12px;">${name}</td></tr>
    <tr><td style="padding:8px 12px;font-weight:600;">Email</td><td style="padding:8px 12px;">${email || "&mdash;"}</td></tr>
    <tr><td style="padding:8px 12px;font-weight:600;">WhatsApp</td><td style="padding:8px 12px;">${whatsapp || "&mdash;"}</td></tr>
    <tr><td style="padding:8px 12px;font-weight:600;">Package / Destination</td><td style="padding:8px 12px;">${packageOrDestination}</td></tr>
  </table>
  <h3 style="margin:20px 0 6px;font-size:14px;color:#334155;">Conversation Summary</h3>
  <p style="margin:0 0 16px;font-size:14px;line-height:1.5;">${summary}</p>
  ${itineraryRow}
  <p style="margin-top:24px;font-size:11px;color:#94a3b8;">Received via Musafir (chat) &middot; Reply directly to the customer, not to this email.</p>
</div>`;
})() }}
